-- chair-step: inverse of read_lane_v2_b3_61_platform_categories — un-enrolls platform.categories from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'platform' and table_name = 'categories' and is_active);
select iam.apply_rls('platform', 'categories', (select token from platform.entity_types where schema_name = 'platform' and table_name = 'categories' and is_active), (select rls_variant from platform.entity_types where schema_name = 'platform' and table_name = 'categories' and is_active));
